import Foundation

enum ExtraASEQuestions {
    private struct Scenario {
        let prompt: String
        let correct: String
        let wrong1: String
        let wrong2: String
        let wrong3: String
        let explanation: String
    }

    /// 20 diagnostic concepts per ASE area, each rendered in three shuffled variants.
    /// This gives 60 questions per area before the original seed question is added.
    static let all: [ASEQuestion] = buildBank()

    private static func buildBank() -> [ASEQuestion] {
        var result: [ASEQuestion] = []
        let areas: [(String, [Scenario])] = [
            ("A1", a1), ("A2", a2), ("A3", a3), ("A4", a4),
            ("A5", a5), ("A6", a6), ("A7", a7), ("A8", a8)
        ]

        let leadIns = [
            "",
            "During diagnosis of a second vehicle with the same symptom, ",
            "After verifying the customer concern, "
        ]

        for (area, scenarios) in areas {
            for (scenarioIndex, scenario) in scenarios.enumerated() {
                for variant in 0..<3 {
                    let raw = [scenario.correct, scenario.wrong1, scenario.wrong2, scenario.wrong3]
                    let shift = (scenarioIndex + variant) % 4
                    let rotated = (0..<4).map { raw[($0 + shift) % 4] }
                    let ids = ["A", "B", "C", "D"]
                    let correctIndex = rotated.firstIndex(of: scenario.correct) ?? 0
                    result.append(
                        ASEQuestion(
                            id: String(format: "bank-%@-%02d-%d", area, scenarioIndex + 1, variant + 1),
                            area: area,
                            question: leadIns[variant] + scenario.prompt,
                            choices: zip(ids, rotated).map { ASEChoice(id: $0.0, text: $0.1) },
                            correctID: ids[correctIndex],
                            explanation: scenario.explanation
                        )
                    )
                }
            }
        }
        return result
    }

    private static func s(_ prompt: String, _ correct: String, _ wrong1: String, _ wrong2: String, _ wrong3: String, _ explanation: String) -> Scenario {
        Scenario(prompt: prompt, correct: correct, wrong1: wrong1, wrong2: wrong2, wrong3: wrong3, explanation: explanation)
    }

