extension AppData {
    var trainingQuestions: [ASEQuestion] {
        aseQuestions + ExtraASEQuestions.all
    }

    /// Builds a different 20-question practice test each time.
    /// Generated questions are grouped by concept so the same concept is not repeated
    /// twice in a single test even though each concept has multiple variants in the bank.
    func practiceTest(area: String, questionCount: Int = 20) -> [ASEQuestion] {
        let pool = trainingQuestions.filter { $0.area == area }
        let grouped = Dictionary(grouping: pool) { question -> String in
            let parts = question.id.split(separator: "-")
            if question.id.hasPrefix("bank-"), parts.count >= 3 {
                return parts.prefix(3).joined(separator: "-")
            }
            return question.id
        }

        var picked = grouped.values.compactMap { $0.randomElement() }.shuffled()
        if picked.count < questionCount {
            let pickedIDs = Set(picked.map(\.id))
            picked += pool.filter { !pickedIDs.contains($0.id) }.shuffled()
        }
        return Array(picked.prefix(min(questionCount, picked.count)))
    }
}
